// Catálogo de asignaturas de la UC. Se descarga aparte y solo cuando alguien
// busca un ramo: son ~660 KB que no tienen por qué pagar quienes estudian en
// otra universidad.
//
// ORIGEN: catalogo.uc.cl, las 48 escuelas, 13.461 asignaturas vigentes de
// pregrado. Nada de esto está escrito a mano.
//
// FORMA: [sigla, nombre, créditos].
//
// CRÉDITOS. Cada fila lleva los de SU sigla, tal como los da el catálogo
// oficial. No se promedia ni se elige entre variantes: "Práctica Clínica
// Medicina Interna" existe con 6 créditos en MOM400 y con 50 en MOM401D, y
// están las dos, cada una con lo suyo. Elegir un valor para representarlas a
// todas le descuadraría el promedio de carrera a quien agregue ese ramo, y se
// vería igual de oficial que los demás.
//
// NOMBRES REPETIDOS. Dos siglas con el mismo nombre son dos ramos que el
// estudiante puede elegir. No se colapsan: la alternativa lleva su código en la
// etiqueta, la misma convención que ya usa CREDITOS_UC en data.js.
//
// Pero donde la app YA resolvió esa elección a mano, este archivo no mete
// opciones nuevas. El plan común de Ingeniería ofrece Dinámica de FIS1514 o de
// ICE1514, CREDITOS_UC ya lo dice y eso funcionaba bien; agregarle una tercera
// sigla del catálogo sin saber si pertenece a ese plan sería ensuciar algo que
// estaba curado. Son 1.191 alternativas omitidas por esa razón.
//
// FUERA QUEDARON los 417 cupos del plan de estudios ("Optativo Electivo",
// "Créditos por Doble Título"): no nombran una asignatura, nombran un hueco.
//
// TILDES. El catálogo oficial las trae casi sin tildes ("Botanica",
// "Investigacion"). Se restauraron con el vocabulario que las mallas de este
// repo ya tenían bien escrito, más terminaciones que en español no fallan
// (-ción, -logía, -grafía, -ática). Lo que no cae en ninguna de las dos queda
// como lo manda la UC: no se adivina.
//
// ESCUELAS_UC va vacío a propósito. Tras juntar el mismo ramo dictado por
// varias escuelas, la escuela dejaba de ser un dato confiable y nada en la app
// la usa. La variable se conserva porque el cargador la espera.
var ESCUELAS_UC=[];
